/**
 * Billing-period arithmetic: where a period ends, how many months it spans and
 * how much of it is left when something changes in the middle of it.
 *
 * Everything is computed in UTC. A period runs from its start up to (not
 * including) its end, and the next period starts exactly where this one ended.
 */
import { parseIso } from "@/lib/date";
import { toIsoTimestamp } from "@/types/common";
import type { BillingInterval } from "@/types/billing";
import type { IsoTimestamp } from "@/types/common";

const DAY_MS = 24 * 60 * 60 * 1000;

/** Months one period of `interval` covers: the multiplier on the monthly price. */
export function monthsInInterval(interval: BillingInterval): number {
  return interval === "annual" ? 12 : 1;
}

/**
 * The end of the period that starts at `start`: the same day of the month one
 * month (or twelve) later at the same time of day, clamped to that month's
 * last day when it has no such day — 31 January → 28 February, 29 February →
 * 28 February of the next year. The clamp is not undone later: a period
 * starting 28 February ends 28 March.
 */
export function periodEndAfter(
  start: IsoTimestamp | Date,
  interval: BillingInterval,
): IsoTimestamp {
  const from = start instanceof Date ? start : parseIso(start);
  const monthIndex = from.getUTCMonth() + monthsInInterval(interval);
  const year = from.getUTCFullYear() + Math.floor(monthIndex / 12);
  const month = monthIndex % 12;
  const lastDay = new Date(Date.UTC(year, month + 1, 0)).getUTCDate();

  const end = new Date(from.getTime());
  end.setUTCFullYear(year, month, Math.min(from.getUTCDate(), lastDay));
  return toIsoTimestamp(end);
}

/**
 * Whole or started days from `at` to the period end — 14 days and 22 hours
 * left count as 15. None once the end has been reached.
 */
export function daysLeftInPeriod(at: Date, periodEnd: IsoTimestamp): number {
  const remaining = parseIso(periodEnd).getTime() - at.getTime();
  return remaining > 0 ? Math.ceil(remaining / DAY_MS) : 0;
}

/** Whole days between the period's start and end, rounded, at least one. */
export function daysInPeriod(
  periodStart: IsoTimestamp,
  periodEnd: IsoTimestamp,
): number {
  const length = parseIso(periodEnd).getTime() - parseIso(periodStart).getTime();
  return Math.max(1, Math.round(length / DAY_MS));
}

/**
 * The share of a full-period charge that falls in what is left of the period
 * at `at`, rounded down to whole cents.
 */
export function prorateCents(
  fullPeriodCents: number,
  at: Date,
  periodStart: IsoTimestamp,
  periodEnd: IsoTimestamp,
): number {
  if (fullPeriodCents <= 0) return 0;
  const left = daysLeftInPeriod(at, periodEnd);
  if (left === 0) return 0;
  return Math.floor(
    (fullPeriodCents * left) / daysInPeriod(periodStart, periodEnd),
  );
}

