/**
 * The full charge for one period: the plan's monthly price per seat × seats ×
 * the months the period spans. Zero on the free plan.
 */
export function periodChargeCents(
  plan: PlanId,
  seats: number,
  interval: BillingInterval,
): number {
  return (
