/**
 * Raises one invoice and announces it as `billing.invoice_issued` — the audit
 * log and the owner's notification hang off that event. A zero charge raises
 * nothing and returns `null`.
 */
export async function issueInvoice(
  orgId: OrgId,
  charge: {
    amountCents: number;
    periodStart: IsoTimestamp;
    periodEnd: IsoTimestamp;
  },
  issuedBy: { actorId: UserId | null; at: Date },
): Promise<Invoice | null> {
  if (charge.amountCents <= 0) return null;

  const issuedAt = toIsoTimestamp(issuedBy.at);
  const invoice = await invoiceRepo.insertInvoice(
    orgId,
    {
      orgId,
      number: await invoiceRepo.nextInvoiceNumber(orgId),
      amountCents: charge.amountCents,
      currency: INVOICE_CURRENCY,
      periodStart: charge.periodStart,
      periodEnd: charge.periodEnd,
      paidAt: null,
    },
    issuedAt,
  );

  await emit("billing.invoice_issued", {
    orgId,
    actorId: issuedBy.actorId,
    occurredAt: issuedAt,
    invoiceId: invoice.id,
    invoiceNumber: invoice.number,
