/**
 * Moves subscriptions on to their next period, invoices every renewed paid period and ends cancellations that are due.
 *
 * Must call (do not reimplement): emit, issueInvoice, periodChargeCents, periodEndAfter
 */
import { periodEndAfter } from "@/lib/billing-period";
import { parseIso } from "@/lib/date";
import { emit } from "@/lib/event-bus";
import { createLogger } from "@/lib/logger";
import * as subscriptionRepo from "@/server/repositories/subscription-repository";
import {
  issueInvoice,
  periodChargeCents,
} from "@/server/services/billing-service";
import { toIsoTimestamp } from "@/types/common";
import { runJob } from "./types";
import type { JobResult } from "@/server/jobs/types";
import type { Subscription } from "@/types/billing";

/** Subscriptions read per page; the sweep pages until every org is seen. */
const PAGE_SIZE = 100;

/** Where an ended cancellation lands. */
const FALLBACK_PLAN = "free" as const;

const logger = createLogger("billing-renewal-job");

/**
 * The billing clock. Every live organization's subscription is looked at:
 *
 *  - `active` with its period end at or before `now`: one new period per
 *    elapsed interval until the period end lies after `now`, each new paid
 *    period invoiced in full at the seat count of the moment;
 *  - `canceled` with its cancellation at or before `now`: the org drops to an
 *    active free plan whose first monthly period starts at the cancellation
 *    date, announced as `billing.plan_changed` with no actor;
 *  - `trialing` and `past_due` are not this job's business.
 *
 * Replay-safe: every write is a compare-and-set on the state it was decided
 * from, and once a subscription is settled its period ends after `now`, so a
 * second run at the same instant finds nothing to do.
 */
export async function runBillingRenewalJob(now: Date): Promise<JobResult> {
  return runJob("billing-renewal", async (result) => {
    let afterId: string | null = null;

    for (;;) {
      const page = await subscriptionRepo.listSubscriptionsOfLiveOrgs(
        afterId,
        PAGE_SIZE,
      );
      if (page.length === 0) break;

      for (const subscription of page) {
        try {
          if (await settle(subscription, now)) result.processed += 1;
        } catch (error) {
          result.failed += 1;
          logger.error("billing renewal failed", {
            orgId: subscription.orgId,
            reason: error instanceof Error ? error.message : String(error),
          });
        }
