/**
 * Subscriptions renew period by period and are invoiced: the period
 * arithmetic, the renewal job, cancellations taking effect, and the prorated
 * charges for seat and plan changes made in the middle of a period.
 */
import { afterAll, afterEach, beforeAll, describe, expect, it, vi } from "vitest";

vi.mock("@/lib/id", () => import("./_support/doubles/id"));
vi.mock("@/lib/logger", async () => (await import("./_support/doubles/misc")).loggerModule);

import { eq } from "drizzle-orm";
import { periodEndAfter, prorateCents } from "@/lib/billing-period";
import { subscribe } from "@/lib/event-bus";
import { getDb, subscriptions } from "@/server/db";
import { runBillingRenewalJob } from "@/server/jobs/billing-renewal-job";
import * as orgRepo from "@/server/repositories/organization-repository";
import * as subscriptionRepo from "@/server/repositories/subscription-repository";
import { listActivity, registerActivityListeners } from "@/server/services/activity-service";
import * as billingService from "@/server/services/billing-service";
import { listNotifications } from "@/server/services/notification-service";
import { toIsoTimestamp } from "@/types/common";
import { createTenant, useTemporaryDatabase } from "./_support/fixtures";
import type { Tenant } from "./_support/fixtures";
import type { Subscription } from "@/types/billing";
import type { IsoTimestamp, OrgId } from "@/types/common";
import type { TaskflowEventMap, TaskflowEventType, Unsubscribe } from "@/types/event";

let cleanup: () => void;
let detachActivity: Unsubscribe;
const detachers: Unsubscribe[] = [];

const stamp = (value: string) => value as IsoTimestamp;

function capture<K extends TaskflowEventType>(type: K): TaskflowEventMap[K][] {
  const seen: TaskflowEventMap[K][] = [];
  detachers.push(
    subscribe(type, (payload) => {
      seen.push(payload);
    }),
  );
  return seen;
}

async function setSubscription(
  orgId: OrgId,
  patch: Partial<typeof subscriptions.$inferInsert>,
): Promise<Subscription> {
  getDb()
    .update(subscriptions)
    .set(patch)
    .where(eq(subscriptions.orgId, orgId))
    .run();
  const subscription = await subscriptionRepo.findSubscription(orgId);
  if (!subscription) throw new Error("no subscription");
  return subscription;
}

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
  detachActivity = registerActivityListeners();
});

afterEach(() => {
  while (detachers.length > 0) detachers.pop()?.();
  vi.useRealTimers();
});

afterAll(() => {
  detachActivity();
  cleanup();
});

describe("billing periods", () => {
  it("ends a monthly period on the same day next month, clamped to the month's end", () => {
    expect(periodEndAfter(stamp("2026-01-15T09:30:00.000Z"), "monthly")).toBe(
      "2026-02-15T09:30:00.000Z",
    );
    expect(periodEndAfter(stamp("2026-01-31T09:30:00.000Z"), "monthly")).toBe(
      "2026-02-28T09:30:00.000Z",
    );
    expect(periodEndAfter(stamp("2026-02-28T09:30:00.000Z"), "monthly")).toBe(
      "2026-03-28T09:30:00.000Z",
    );
    expect(periodEndAfter(stamp("2026-12-31T00:00:00.000Z"), "monthly")).toBe(
      "2027-01-31T00:00:00.000Z",
    );
  });

  it("ends an annual period on the same day next year", () => {
    expect(periodEndAfter(stamp("2028-02-29T12:00:00.000Z"), "annual")).toBe(
      "2029-02-28T12:00:00.000Z",
    );
    expect(periodEndAfter(stamp("2026-06-01T00:00:00.000Z"), "annual")).toBe(
      "2027-06-01T00:00:00.000Z",
    );
  });

  it("counts a started day as a whole day left, and none once the period is over", () => {
    const start = stamp("2026-04-01T00:00:00.000Z");
    const end = stamp("2026-05-01T00:00:00.000Z");

    // 14 days and 22 hours left count as 15 of 30.
    expect(prorateCents(3_000, new Date("2026-04-16T02:00:00.000Z"), start, end)).toBe(1_500);
    expect(prorateCents(1_000, new Date("2026-04-21T00:00:00.000Z"), start, end)).toBe(333);
    expect(prorateCents(3_000, new Date("2026-05-01T00:00:00.000Z"), start, end)).toBe(0);
  });
});

