/**
 * Subscriptions renew period by period and are invoiced: the period
 * arithmetic, the renewal job, cancellations taking effect, and the prorated
 * charges for seat and plan changes made in the middle of a period.
 */
import { afterAll, afterEach, beforeAll, describe, expect, it, vi } from "vitest";

vi.mock("@/lib/id", () => import("./_support/doubles/id"));
vi.mock("@/lib/logger", async () => (await import("./_support/doubles/misc")).loggerModule);

import { eq } from "drizzle-orm";
import { periodEndAfter, prorateCents } from "@/lib/billing-period";
import { subscribe } from "@/lib/event-bus";
import { getDb, subscriptions } from "@/server/db";
import { runBillingRenewalJob } from "@/server/jobs/billing-renewal-job";
import * as orgRepo from "@/server/repositories/organization-repository";
import * as subscriptionRepo from "@/server/repositories/subscription-repository";
import { listActivity, registerActivityListeners } from "@/server/services/activity-service";
import * as billingService from "@/server/services/billing-service";
import { listNotifications } from "@/server/services/notification-service";
import { toIsoTimestamp } from "@/types/common";
import { createTenant, useTemporaryDatabase } from "./_support/fixtures";
import type { Tenant } from "./_support/fixtures";
import type { Subscription } from "@/types/billing";
import type { IsoTimestamp, OrgId } from "@/types/common";
import type { TaskflowEventMap, TaskflowEventType, Unsubscribe } from "@/types/event";

let cleanup: () => void;
let detachActivity: Unsubscribe;
const detachers: Unsubscribe[] = [];

const stamp = (value: string) => value as IsoTimestamp;

function capture<K extends TaskflowEventType>(type: K): TaskflowEventMap[K][] {
  const seen: TaskflowEventMap[K][] = [];
  detachers.push(
    subscribe(type, (payload) => {
      seen.push(payload);
    }),
  );
  return seen;
}

async function setSubscription(
  orgId: OrgId,
  patch: Partial<typeof subscriptions.$inferInsert>,
): Promise<Subscription> {
  getDb()
    .update(subscriptions)
    .set(patch)
    .where(eq(subscriptions.orgId, orgId))
    .run();
  const subscription = await subscriptionRepo.findSubscription(orgId);
  if (!subscription) throw new Error("no subscription");
  return subscription;
}

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
  detachActivity = registerActivityListeners();
});

afterEach(() => {
  while (detachers.length > 0) detachers.pop()?.();
  vi.useRealTimers();
});

afterAll(() => {
  detachActivity();
  cleanup();
});

describe("billing periods", () => {
  it("ends a monthly period on the same day next month, clamped to the month's end", () => {
    expect(periodEndAfter(stamp("2026-01-15T09:30:00.000Z"), "monthly")).toBe(
      "2026-02-15T09:30:00.000Z",
    );
    expect(periodEndAfter(stamp("2026-01-31T09:30:00.000Z"), "monthly")).toBe(
      "2026-02-28T09:30:00.000Z",
    );
    expect(periodEndAfter(stamp("2026-02-28T09:30:00.000Z"), "monthly")).toBe(
      "2026-03-28T09:30:00.000Z",
    );
    expect(periodEndAfter(stamp("2026-12-31T00:00:00.000Z"), "monthly")).toBe(
      "2027-01-31T00:00:00.000Z",
    );
  });

  it("ends an annual period on the same day next year", () => {
    expect(periodEndAfter(stamp("2028-02-29T12:00:00.000Z"), "annual")).toBe(
      "2029-02-28T12:00:00.000Z",
    );
    expect(periodEndAfter(stamp("2026-06-01T00:00:00.000Z"), "annual")).toBe(
      "2027-06-01T00:00:00.000Z",
    );
  });

  it("counts a started day as a whole day left, and none once the period is over", () => {
    const start = stamp("2026-04-01T00:00:00.000Z");
    const end = stamp("2026-05-01T00:00:00.000Z");

    // 14 days and 22 hours left count as 15 of 30.
    expect(prorateCents(3_000, new Date("2026-04-16T02:00:00.000Z"), start, end)).toBe(1_500);
    expect(prorateCents(1_000, new Date("2026-04-21T00:00:00.000Z"), start, end)).toBe(333);
    expect(prorateCents(3_000, new Date("2026-05-01T00:00:00.000Z"), start, end)).toBe(0);
  });
});

describe("the billing renewal job", () => {
  it("renews one period per elapsed interval and invoices each paid period", async () => {
    const tenant = await createTenant("renew-behind", "starter");
    await setSubscription(tenant.org.id, {
      status: "active",
      seats: 3,
      currentPeriodStart: "2026-01-31T10:00:00.000Z",
      currentPeriodEnd: "2026-02-28T10:00:00.000Z",
    });
    const issued = capture("billing.invoice_issued");

    const now = new Date("2026-05-01T00:00:00.000Z");
    const result = await runBillingRenewalJob(now);

    expect(result.kind).toBe("billing-renewal");
    expect(result.failed).toBe(0);

    const subscription = await subscriptionRepo.findSubscription(tenant.org.id);
    expect(subscription).toMatchObject({
      status: "active",
      currentPeriodStart: "2026-04-28T10:00:00.000Z",
      currentPeriodEnd: "2026-05-28T10:00:00.000Z",
    });

    const invoices = await billingService.listInvoices(tenant.actors.owner, tenant.org.id);
    expect(invoices.map((invoice) => [invoice.periodStart, invoice.periodEnd])).toEqual([
      ["2026-04-28T10:00:00.000Z", "2026-05-28T10:00:00.000Z"],
      ["2026-03-28T10:00:00.000Z", "2026-04-28T10:00:00.000Z"],
      ["2026-02-28T10:00:00.000Z", "2026-03-28T10:00:00.000Z"],
    ]);
    for (const invoice of invoices) {
      expect(invoice).toMatchObject({ amountCents: 2_700, currency: "usd", paidAt: null });
    }
    expect(new Set(invoices.map((invoice) => invoice.number)).size).toBe(3);
    expect(issued).toHaveLength(3);
    expect(issued[0]).toMatchObject({ orgId: tenant.org.id, actorId: null, amountCents: 2_700 });

    // Replaying at the same instant changes nothing.
    const again = await runBillingRenewalJob(now);
    expect(again.processed).toBe(0);
    expect(issued).toHaveLength(3);
    expect(await billingService.listInvoices(tenant.actors.owner, tenant.org.id)).toHaveLength(3);
    expect(await subscriptionRepo.findSubscription(tenant.org.id)).toEqual(subscription);
  });

  it("invoices annual periods for twelve months", async () => {
    const tenant = await createTenant("renew-annual", "growth");
    await setSubscription(tenant.org.id, {
      status: "active",
      interval: "annual",
      seats: 2,
      currentPeriodStart: "2025-03-01T00:00:00.000Z",
      currentPeriodEnd: "2026-03-01T00:00:00.000Z",
    });

    await runBillingRenewalJob(new Date("2026-03-01T00:00:00.000Z"));

    const invoices = await billingService.listInvoices(tenant.actors.owner, tenant.org.id);
    expect(invoices).toHaveLength(1);
    expect(invoices[0]).toMatchObject({
      amountCents: 1_900 * 2 * 12,
      periodStart: "2026-03-01T00:00:00.000Z",
      periodEnd: "2027-03-01T00:00:00.000Z",
    });
  });

  it("moves free periods on without invoicing them", async () => {
    const tenant = await createTenant("renew-free", "free");
    await setSubscription(tenant.org.id, {
      currentPeriodStart: "2026-01-10T00:00:00.000Z",
      currentPeriodEnd: "2026-02-10T00:00:00.000Z",
    });

    await runBillingRenewalJob(new Date("2026-03-15T00:00:00.000Z"));

    expect(await subscriptionRepo.findSubscription(tenant.org.id)).toMatchObject({
      currentPeriodStart: "2026-03-10T00:00:00.000Z",
      currentPeriodEnd: "2026-04-10T00:00:00.000Z",
    });
    expect(await billingService.listInvoices(tenant.actors.owner, tenant.org.id)).toHaveLength(0);
  });

  it("ends a cancellation on its date, moving the org to the free plan", async () => {
    const tenant = await createTenant("renew-cancel", "growth");
    await setSubscription(tenant.org.id, {
      status: "canceled",
      seats: 4,
      currentPeriodStart: "2026-01-05T00:00:00.000Z",
      currentPeriodEnd: "2026-02-05T00:00:00.000Z",
      cancelAt: "2026-02-05T00:00:00.000Z",
    });
    const changed = capture("billing.plan_changed");
    const issued = capture("billing.invoice_issued");

    const now = new Date("2026-02-06T00:00:00.000Z");
    await runBillingRenewalJob(now);
    await runBillingRenewalJob(now);

    expect(await subscriptionRepo.findSubscription(tenant.org.id)).toMatchObject({
      plan: "free",
      status: "active",
      interval: "monthly",
      cancelAt: null,
      currentPeriodStart: "2026-02-05T00:00:00.000Z",
      currentPeriodEnd: "2026-03-05T00:00:00.000Z",
    });
    expect(changed).toEqual([
      expect.objectContaining({ orgId: tenant.org.id, actorId: null, from: "growth", to: "free" }),
    ]);
    expect(issued).toHaveLength(0);
  });

  it("leaves a cancellation alone before its date, whatever the period end says", async () => {
    const tenant = await createTenant("renew-cancel-later", "starter");
    const before = await setSubscription(tenant.org.id, {
      status: "canceled",
      currentPeriodStart: "2026-01-05T00:00:00.000Z",
      currentPeriodEnd: "2026-02-05T00:00:00.000Z",
      cancelAt: "2026-03-01T00:00:00.000Z",
    });

    await runBillingRenewalJob(new Date("2026-02-20T00:00:00.000Z"));

    expect(await subscriptionRepo.findSubscription(tenant.org.id)).toEqual(before);
    expect(await billingService.listInvoices(tenant.actors.owner, tenant.org.id)).toHaveLength(0);
  });

  it("leaves trials and past-due subscriptions alone", async () => {
    const trial = await createTenant("renew-trial", "growth");
    const pastDue = await createTenant("renew-past-due", "growth");
    const period = {
      currentPeriodStart: "2026-01-01T00:00:00.000Z",
      currentPeriodEnd: "2026-02-01T00:00:00.000Z",
    };
    const trialBefore = await setSubscription(trial.org.id, { status: "trialing", ...period });
    const pastDueBefore = await setSubscription(pastDue.org.id, { status: "past_due", ...period });

    await runBillingRenewalJob(new Date("2026-03-01T00:00:00.000Z"));

    expect(await subscriptionRepo.findSubscription(trial.org.id)).toEqual(trialBefore);
    expect(await subscriptionRepo.findSubscription(pastDue.org.id)).toEqual(pastDueBefore);
  });

  it("skips archived organizations", async () => {
    const tenant = await createTenant("renew-archived", "starter");
    const before = await setSubscription(tenant.org.id, {
      status: "active",
      currentPeriodStart: "2026-01-01T00:00:00.000Z",
      currentPeriodEnd: "2026-02-01T00:00:00.000Z",
    });
    await orgRepo.archiveOrg(tenant.org.id);

    await runBillingRenewalJob(new Date("2026-03-01T00:00:00.000Z"));

    expect(await subscriptionRepo.findSubscription(tenant.org.id)).toEqual(before);
  });

  it("audits every invoice and tells only the owner about it", async () => {
    const tenant = await createTenant("renew-announce", "starter");
    await setSubscription(tenant.org.id, {
      status: "active",
      currentPeriodStart: "2026-01-01T00:00:00.000Z",
      currentPeriodEnd: "2026-02-01T00:00:00.000Z",
    });

    await runBillingRenewalJob(new Date("2026-02-01T00:00:00.000Z"));

    const audit = await listActivity(tenant.actors.owner, {
      orgId: tenant.org.id,
      action: ["billing.invoice_issued"],
      limit: 25,
      cursor: null,
    });
    expect(audit.items).toHaveLength(1);
    expect(audit.items[0]).toMatchObject({
      subjectKind: "subscription",
      subjectId: tenant.org.id,
    });

    for (const role of ["owner", "admin", "member", "viewer"] as const) {
      const page = await listNotifications(tenant.actors[role], {
        orgId: tenant.org.id,
        recipientId: tenant.userIds[role],
        unreadOnly: false,
        kind: ["invoice_issued"],
        limit: 25,
        cursor: null,
      });
      expect(page.items).toHaveLength(role === "owner" ? 1 : 0);
    }
  });
});

